<svelte:options runes={true} />

<script lang="ts">
  // Agents and scoped tokens: workspace administration for owners/admins only.
  import { formatDate } from '../../../lib/state';
  import { scopeOptions } from '../../constants';
  import { createAgent, createToken, deleteToken, loadAgents, toggleScope, toggleTokenProject } from '../../settings';
  import { settings } from '../../state/settings.svelte';
  import { workspace } from '../../state/workspace.svelte';
</script>

{#if settings.agentsError}<div class="inline-alert error content-alert" role="alert"><span>!</span>{settings.agentsError}<button class="text-button" type="button" on:click={loadAgents}>Retry</button></div>{/if}
<div class="settings-section"><div class="settings-section-heading"><div><span class="eyebrow">Coordination</span><h2>Agents &amp; tokens</h2><p>Give software agents scoped access without sharing a human login.</p></div><button class="button primary" type="button" on:click={() => settings.showAgentForm = !settings.showAgentForm}>＋ Add agent</button></div>{#if settings.showAgentForm}<div class="settings-form"><label>Agent name<input bind:value={settings.agentNameDraft} placeholder="Release assistant" /></label><label>Description <span class="optional">Optional</span><textarea rows="2" bind:value={settings.agentDescriptionDraft} placeholder="What is this agent responsible for?"></textarea></label><div class="form-actions"><button class="text-button" type="button" on:click={() => settings.showAgentForm = false}>Cancel</button><button class="button primary" type="button" disabled={!settings.agentNameDraft.trim()} on:click={createAgent}>Create agent</button></div></div>{/if}{#if settings.agentsLoading}<div class="list-skeleton">{#each [1, 2] as item}<div></div>{/each}</div>{:else if !settings.agents.length}<div class="empty-state compact-empty"><div class="empty-icon">✦</div><h3>No agents yet</h3><p>Create a scoped identity for the tools that collaborate with you.</p><button class="button quiet-button" type="button" on:click={() => settings.showAgentForm = true}>Create your first agent</button></div>{:else}<div class="agent-list">{#each settings.agents as agent}<article class="agent-card"><div class="agent-card-header"><span class="agent-avatar">✦</span><div><h3>{agent.name}</h3><p>{agent.description || 'No description'}</p></div><button class="button quiet-button compact-button" type="button" data-token-trigger on:click={() => { settings.selectedAgentId = agent.id; settings.showTokenForm = settings.selectedAgentId === agent.id && !settings.showTokenForm; }}>＋ Token</button></div>{#if agent.tokens?.length}<div class="token-list">{#each agent.tokens as token}<div class="token-row"><span class="token-icon">⌘</span><span class="token-info"><strong>{token.name}</strong><small>{token.scopes.join(' · ')}</small></span><span class="token-date">{token.expires_at ? `Expires ${formatDate(token.expires_at)}` : 'No expiry'}</span><button class="icon-button tiny danger-button" type="button" aria-label={`Revoke ${token.name}`} on:click={() => deleteToken(token)}>×</button></div>{/each}</div>{:else}<div class="agent-no-tokens">No active tokens</div>{/if}{#if settings.showTokenForm && settings.selectedAgentId === agent.id}<div class="token-form"><div class="settings-form"><label>Token name<input bind:value={settings.tokenNameDraft} placeholder="CI deployment token" /></label><fieldset><legend>Scopes</legend><div class="scope-grid">{#each scopeOptions as scope}<label class="check-label"><input type="checkbox" checked={settings.tokenScopes.includes(scope)} on:change={() => toggleScope(scope)} /><span>{scope}</span></label>{/each}</div></fieldset><fieldset><legend>Limit to projects <span class="optional">Optional</span></legend><div class="scope-grid project-checks">{#each workspace.projects as project}<label class="check-label"><input type="checkbox" checked={settings.tokenProjectIds.includes(project.id)} on:change={() => toggleTokenProject(project.id)} /><span>{project.name}</span></label>{/each}</div></fieldset><div class="form-actions"><button class="text-button" type="button" on:click={() => settings.showTokenForm = false}>Cancel</button><button class="button primary" type="button" disabled={!settings.tokenNameDraft.trim() || !settings.tokenScopes.length || settings.tokenCreating} on:click={createToken}>{#if settings.tokenCreating}<span class="button-spinner"></span>{/if}Create token</button></div></div></div>{/if}</article>{/each}</div>{/if}</div>
